WatchFace({
  initView() {
    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Level (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('scene.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Cloud far (IMG)
    W.cl1 = ui.createWidget(ui.widget.IMG, {
      x: px(40),
      y: px(284),
      src: A('act/cloud_1.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Cloud near (IMG)
    W.cl0 = ui.createWidget(ui.widget.IMG, {
      x: px(220),
      y: px(236),
      src: A('act/cloud_0.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Coin (IMG)
    W.coin = ui.createWidget(ui.widget.IMG, {
      x: px(271),
      y: px(100),
      src: A('act/coin_0.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour block (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(20),
      y: px(84),
      src: A('block_hour.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute block (IMG)
    W.qb = ui.createWidget(ui.widget.IMG, {
      x: px(200),
      y: px(84),
      src: A('block_min.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(222),
      minute_startY: px(122),
      minute_zero: 1,
      minute_space: px(-4),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_473v,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(40),
      hour_startY: px(122),
      hour_zero: 1,
      hour_space: px(-4),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Main_42e8,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(225),
      minute_startY: px(198),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Aod_r5qf,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon Aod (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(180),
      y: px(198),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(50),
      hour_startY: px(198),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Aod_r69s,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Goomba (IMG)
    W.gob = ui.createWidget(ui.widget.IMG, {
      x: px(340),
      y: px(320),
      src: A('act/goomba_0.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Power-up (IMG_LEVEL)
    ui.createWidget(ui.widget.IMG_LEVEL, {
      x: px(190),
      y: px(308),
      image_array: img_Power_up_pov6,
      image_length: img_Power_up_pov6.length,
      type: ui.data_type.BATTERY,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Mario (IMG)
    W.mar = ui.createWidget(ui.widget.IMG, {
      x: px(259),
      y: px(296),
      src: A('act/mario_0.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(61),
      y: px(29),
      type: ui.data_type.STEP,
      font_array: img_Steps_p614,
      h_space: px(1),
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Heart rate (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(65),
      y: px(387),
      type: ui.data_type.HEART,
      font_array: img_Heart_rate_84k1,
      h_space: px(1),
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Battery (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(243),
      y: px(387),
      type: ui.data_type.BATTERY,
      font_array: img_Battery_v4wt,
      h_space: px(1),
      align_h: ui.align.LEFT,
      unit_en: A('percent.png'),
      unit_sc: A('percent.png'),
      unit_tc: A('percent.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })


    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // Once a minute Mario jumps, bumps the question block (the minute) and a coin pops out. A Goomba strolls by, clouds drift.
      const MS = 80, BLOCK_Y = 84, MARIO_Y = 296, JUMP_MS = 700, JUMP_H = 72, QX = 200, GOOMBA_S = 36
      const img = (n) => A('act/' + n + '.png')
      let id = null, n = 0, lastMin = -1, t0 = -9999, clock = null
      try { clock = new DCTime() } catch (e) {}
      const minute = () => {
        try { if (clock) { const v = clock.getMinutes(); if (typeof v === 'number' && v >= 0) return v } } catch (e) {}
        try { return new Date().getMinutes() } catch (e) {}
        return 0
      }
      const tick = () => {
        n++
        const now = Date.now(), m = minute()
        if (lastMin >= 0 && m !== lastMin) t0 = now
        lastMin = m
        const t = now - t0
        // Mario: stand, or up and down in a parabola
        const u = Math.min(1, Math.max(0, t / JUMP_MS))
        const rise = t >= 0 && t < JUMP_MS ? Math.round(JUMP_H * 4 * u * (1 - u)) : 0
        W.mar.setProperty(ui.prop.MORE, { x: pxv(259), y: pxv(MARIO_Y - rise), src: img(rise > 0 ? 'mario_1' : 'mario_0') })
        // block bump at the top of the jump, coin pops out
        const tb = t - JUMP_MS / 2
        const bump = tb >= 0 && tb < 220 ? Math.round(-12 * Math.sin(Math.PI * tb / 220)) : 0
        W.qb.setProperty(ui.prop.MORE, { x: pxv(QX), y: pxv(BLOCK_Y + bump) })
        if (tb >= 0 && tb < 620) W.coin.setProperty(ui.prop.MORE, { x: pxv(271), y: pxv(Math.round(BLOCK_Y - 34 - 40 * Math.min(1, tb / 500))), src: img('coin_' + (Math.floor(tb / 70) % 4)) })
        else W.coin.setProperty(ui.prop.MORE, { x: pxv(271), y: pxv(100), src: img('coin_0') })
        // Goomba walks left across the ground
        const gp = (now / 1000 % GOOMBA_S) / GOOMBA_S
        W.gob.setProperty(ui.prop.MORE, { x: pxv(Math.round(390 - gp * 470)), y: pxv(GROUND_Y), src: img('goomba_' + (Math.floor(now / 220) % 2)) })
        // clouds
        W.cl0.setProperty(ui.prop.MORE, { x: pxv(Math.round(((now / 1000) * 6) % 520 - 100)), y: pxv(236), src: img('cloud_0') })
        W.cl1.setProperty(ui.prop.MORE, { x: pxv(Math.round(((now / 1000) * 4 + 260) % 520 - 100)), y: pxv(284), src: img('cloud_1') })
      }
      const GROUND_Y = 320
      const safe = () => { try { tick() } catch (e) {} }
      const start = () => { if (id === null) { try { id = setInterval(safe, MS) } catch (e) {} } }
      const stop = () => { if (id !== null) { try { clearInterval(id) } catch (e) {} id = null } }
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop })
      safe()
      start()
    }
  },

  build() {
    this.initView()
  },
})
